import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"OCSE: install failures and recovery","description":"","frontmatter":{},"headers":[],"relativePath":"components/ocse/ocse-recovery.md","filePath":"components/ocse/ocse-recovery.md"}'),n={name:"components/ocse/ocse-recovery.md"};function r(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="ocse-install-failures-and-recovery" tabindex="-1">OCSE: install failures and recovery <a class="header-anchor" href="#ocse-install-failures-and-recovery" aria-label="Permalink to &quot;OCSE: install failures and recovery&quot;">​</a></h1><p>What happens when an install goes wrong, and why an aborted install does not leave a half-written system behind.</p><h2 id="the-error-page" tabindex="-1">The error page <a class="header-anchor" href="#the-error-page" aria-label="Permalink to &quot;The error page&quot;">​</a></h2><p>Every OCSECL command the wizard runs returns a status. The first failing command stops the wizard: the error page shows</p><ul><li>the <strong>command line</strong> that failed (copied verbatim), and</li><li>the <strong>captured output</strong> of that command (the same text the shell would have printed),</li></ul><p>plus <strong>Retry</strong> and <strong>Back</strong>. Retry re-runs the failed stage; Back returns to the page before it. Nothing else on the machine is touched while the error page is up.</p><h2 id="failure-modes-and-handling" tabindex="-1">Failure modes and handling <a class="header-anchor" href="#failure-modes-and-handling" aria-label="Permalink to &quot;Failure modes and handling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>Failure</th><th>Handling</th></tr></thead><tbody><tr><td>Step 2</td><td>target disk already boots <code>opencube.elf</code></td><td>refused before any write - the existing system stays untouched</td></tr><tr><td>Step 3</td><td>no free gap large enough</td><td>the wizard says so; nothing is written</td></tr><tr><td>Stage 1</td><td><code>mount</code> fails on a stale mount from an earlier failed retry</td><td>the wizard drops the stale mount (<code>umount /mnt</code>) and retries the mount <strong>once</strong> before giving up</td></tr><tr><td>Stage 2</td><td>medium check, recovery-partition carve, extract, boot code or boot flag fails inside <code>install</code></td><td>the sub-step&#39;s own FATAL text names the failing point (<code>extraction failed</code> / <code>/boot/opencube.elf missing after extraction</code> / <code>ocbl-install failed</code> / <code>could not set the boot flag</code>); the boot code is written only after a fully successful extraction that verified <code>/boot/opencube.elf</code> exists</td></tr><tr><td>Stage 3/4</td><td>a config value or the user record does not fit</td><td>refused with a clear error (bounded builders - never truncated, never overflowed)</td></tr><tr><td>Stage 5/6</td><td><code>sync</code>/<code>umount</code> fail</td><td>retried via the error page; the installed files are already on disk, so a later manual <code>sync</code> from OCSECL finishes the job</td></tr></tbody></table><h2 id="recovering-by-hand-with-ocsecl" tabindex="-1">Recovering by hand with OCSECL <a class="header-anchor" href="#recovering-by-hand-with-ocsecl" aria-label="Permalink to &quot;Recovering by hand with OCSECL&quot;">​</a></h2><p>Because the wizard is only a controller over OCSECL, a failed install can be inspected and completed by hand from the shell:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lsdisk                       pick the target</span></span>
<span class="line"><span>lspart hd0                   what did the wizard create?</span></span>
<span class="line"><span>mount hd0p2 /mnt             mount the installed partition</span></span>
<span class="line"><span>ls /mnt                      inspect what was written</span></span>
<span class="line"><span>cat /mnt/etc/opencube.conf   the config keys that made it</span></span>
<span class="line"><span>config set hostname mybox    finish any missing key</span></span>
<span class="line"><span>sync                         flush</span></span>
<span class="line"><span>umount /mnt                  done - reboot</span></span></code></pre></div><p><code>hwcheck</code> re-runs the four hardware checks at any time - the first thing to try when disks misbehave.</p><h2 id="when-the-target-already-has-a-system" tabindex="-1">When the target already has a system <a class="header-anchor" href="#when-the-target-already-has-a-system" aria-label="Permalink to &quot;When the target already has a system&quot;">​</a></h2><p>The existing-system refusal is the outer guard: OCSE never formats, repartitions or installs over a partition that already boots <code>opencube.elf</code>. To reinstall over an old Open Cube OS on purpose, delete the old partition first (<code>rmpart &lt;disk&gt; &lt;n&gt; confirm</code>) or pick a different target - both are explicit, confirmed actions.</p><h2 id="what-install-writes-in-order" tabindex="-1">What <code>install</code> writes, in order <a class="header-anchor" href="#what-install-writes-in-order" aria-label="Permalink to &quot;What \`install\` writes, in order&quot;">​</a></h2><p>Inside stage 2 the <code>install</code> command runs its own fixed sequence, aborting at the first FATAL: an optional dedicated OCIRE recovery partition carve (when the layout calls for one, with <code>boot/ocire.elf</code> on the system volume), the extraction of the payload tar (verified by the presence of <code>/boot/opencube.elf</code>), the OCBL boot code (<code>ocbl-install</code> - image validity, room before the first partition, stage1 + core verify), and finally the boot flag on the created partition.</p><h2 id="after-a-successful-install" tabindex="-1">After a successful install <a class="header-anchor" href="#after-a-successful-install" aria-label="Permalink to &quot;After a successful install&quot;">​</a></h2><p>The final page offers <strong>reboot</strong>. The installed disk carries: the OCOS payload, the OCBL boot code (<code>ocbl-install</code> ran inside <code>install</code>), the boot flag on the created partition, the config keys and the user record. On the A/B recovery-disk layout, the recovery disk is prepared separately (see the OCBL pages) - OCSE&#39;s <code>install</code> targets the plain single-system layout.</p><p>See also: <a href="./../ocbl/ocbl-troubleshooting.html">OCBL troubleshooting and status codes</a> for what the boot loader reports on the first boots of the installed system.</p>`,19)])])}const f=t(n,[["render",r]]);export{u as __pageData,f as default};
